#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    #pragma omp parallel
    {
        std::array<size_t, 4> local = {0, 0, 0, 0};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Treat axes as belonging to the "positive" side, matching the example.
            const bool xPos = (x >= 0.0);
            const bool yPos = (y >= 0.0);

            // Bins: [Q1, Q2, Q3, Q4] where:
            // Q1: x>=0,y>=0 ; Q2: x<0,y>=0 ; Q3: x<0,y<0 ; Q4: x>=0,y<0
            const int q = (xPos ? (yPos ? 0 : 3) : (yPos ? 1 : 2));
            local[static_cast<std::size_t>(q)]++;
        }

        #pragma omp critical
        {
            bins[0] += local[0];
            bins[1] += local[1];
            bins[2] += local[2];
            bins[3] += local[3];
        }
    }
}
